const input = $json.body ?? $json;
const num = (v) => { const n = Number(v); return Number.isFinite(n) ? n : null; };

const dealId = input.deal_id;
const leadId = input.lead_id;
const propertyId = input.property_id;
const decision = String(input.acquisition_decision ?? input.controller_status ?? "").toLowerCase();
const askingPrice = num(input.asking_price);
const adjustedMao = num(input.adjusted_mao ?? input.dynamic_mao);
const projectedProfit = num(input.projected_assignment_profit ?? input.projected_profit);
const motivation = String(input.motivation ?? "").toLowerCase();
const assetClass = String(input.asset_class ?? input.asset_type ?? "residential_wholesale").toLowerCase();
const preferredChannel = String(input.preferred_channel ?? input.channel ?? "sms").toLowerCase();
const sellerName = String(input.seller_name ?? input.first_name ?? "there").trim();
const blockers = Array.isArray(input.blockers) ? input.blockers : [];
const dnc = input.dnc === true || input.do_not_contact === true;

const identityReady = Boolean(dealId && leadId && propertyId);
const validMao = adjustedMao !== null && adjustedMao >= 0;
const validAsking = askingPrice !== null && askingPrice >= 0;
const validProfit = projectedProfit !== null && projectedProfit > 0;
const decisionReady = decision === "pursue" || decision === "negotiate";

let openingOffer = null;
let negotiationTarget = null;
let strategy = "standard_value_based";
if (motivation.includes("urgent") || motivation.includes("distress") || motivation.includes("high")) strategy = "speed_and_certainty";
if (assetClass.includes("land")) strategy = "land_exit_and_development_economics";
if (assetClass.includes("multi") || assetClass.includes("apartment")) strategy = "cashflow_and_exit_economics";

if (validMao && validAsking && validProfit) {
  if (decision === "pursue") {
    openingOffer = Math.min(adjustedMao, askingPrice);
    negotiationTarget = openingOffer;
  } else {
    const discountFactor = strategy === "speed_and_certainty" ? 0.93 : 0.90;
    openingOffer = Math.min(adjustedMao, askingPrice * discountFactor);
    negotiationTarget = Math.min(adjustedMao, Math.max(openingOffer, askingPrice * 0.97));
  }
  openingOffer = Math.round(openingOffer * 100) / 100;
  negotiationTarget = Math.round(negotiationTarget * 100) / 100;
}

const validOffer = openingOffer !== null && negotiationTarget !== null && openingOffer >= 0 && negotiationTarget >= openingOffer && negotiationTarget <= adjustedMao;

let status = "offer_package_ready";
let nextWorkflow = "WF-335";
let reason = "Acquisition decision is supported and the seller offer package is within the dynamic MAO ceiling.";

if (!identityReady || !decisionReady || !validMao || !validAsking || !validProfit || !validOffer) {
  status = "incomplete";
  nextWorkflow = "WF-333";
  reason = "Acquisition decision, identity, economics, or offer inputs are incomplete/invalid.";
} else if (dnc || blockers.length > 0) {
  status = "blocked";
  nextWorkflow = "WF-126";
  reason = "DNC or active blockers prevent seller outreach.";
}

const sellerMessage = status === "offer_package_ready"
  ? \`Hi \${sellerName}, I’m reviewing the property and would like to discuss an offer. I’m looking at around $\${openingOffer.toLocaleString()} based on the property and current numbers. If that works for you, I can move quickly. Would you be open to talking about it?\`
  : "";

return [{
  json: {
    ...input,
    workflow_id: "WF-334",
    controller_status: status,
    offer_package_status: status,
    deal_id: dealId,
    lead_id: leadId,
    property_id: propertyId,
    acquisition_decision: decision,
    asset_class: assetClass,
    negotiation_strategy: strategy,
    asking_price: askingPrice,
    adjusted_mao: adjustedMao,
    opening_offer: openingOffer,
    negotiation_target: negotiationTarget,
    projected_assignment_profit: projectedProfit,
    preferred_channel: preferredChannel === "email" ? "email" : "sms",
    seller_message: sellerMessage,
    seller_review_required: true,
    hard_mao_guardrail: true,
    rule_70_percent: "secondary_reference_only",
    reason,
    next_workflow: nextWorkflow,
    requires_human_review: status === "offer_package_ready" || status === "blocked",
    idempotency_key: input.idempotency_key ?? \`wf-334:\${dealId ?? "unknown"}:\${propertyId ?? "unknown"}:\${openingOffer ?? "unknown"}\`
  }
}];
